func (this *Image) AdaptImageDataIfDisabledOrGray(dataAtZoom *DPIUtilElementAtZoom) *DPIUtilElementAtZoom {
	return NewDPIUtilElementAtZoom(this.AdaptImageDataIfDisabledOrGrayData(jrt.Cast[*ImageData](dataAtZoom.Element())), dataAtZoom.Zoom())
}

func (this *Image) AdaptImageDataIfDisabledOrGrayData(dataLike ImageDataLike) *ImageData {
	var data *ImageData
	if dataLike != nil {
		data = dataLike.AsImageData()
	}
	_ = data
	var returnImageData *ImageData = nil
	switch this.styleFlag {
	case IMAGE_DISABLE:
		{
			var newData *ImageData = this.ApplyDisableImageData(data, data.Height, data.Width)
			returnImageData = newData
			break
		}
	case IMAGE_GRAY:
		{
			var newData *ImageData = this.ApplyGrayImageData(data, data.Height, data.Width)
			returnImageData = newData
			break
		}
	default:
		{
			returnImageData = data
			break
		}
	}
	return returnImageData
}
